SELECT DISTINCT p.perm_code FROM rbac_role_permission rp INNER JOIN rbac_permission p ON p.account_id = rp.account_id AND p.id = rp.permission_id INNER JOIN rbac_role r ON r.account_id = rp.account_id AND r.id = rp.role_id WHERE rp.account_id = #{accountId} AND r.status = 1 AND r.deleted = 0 AND p.status = 1 AND p.deleted = 0 AND rp.role_id IN
#{roleId}
ORDER BY p.perm_code

SELECT DISTINCT perm_code FROM rbac_permission WHERE account_id = #{accountId} AND status = 1 AND deleted = 0 AND id IN
#{permissionId}
ORDER BY perm_code
